//! Questions, answers, pauses, waits, and durable task-thread notes.

use super::*;

impl LodestarStore {
    /// Park a claimed task with a durable question (ADR-0020): owner-guarded
    /// transition to `needs_input` that clears the live lease but keeps the owner
    /// and `claim_started_at` evidence window, records `parked_at`, and appends
    /// the question to the task's append-only thread.
    ///
    /// `audience` addresses the question at a peer agent instead of a human
    /// (ADR-0046). The transition is identical either way: the owner cannot
    /// proceed until answered, so it parks and the parking grace still protects
    /// the task from a peer that never replies. Addressing changes who is
    /// expected to answer, never what the task does while it waits.
    pub fn ask_question(
        &self,
        id: &str,
        agent: &str,
        question: &str,
        audience: Option<&str>,
        now: i64,
    ) -> Result<bool> {
        let audience = normalize_audience(audience);
        if audience.as_deref() == Some(agent) {
            return Err(LodestarError::Invalid(format!(
                "task {id}: an agent cannot address a question to itself"
            )));
        }
        let transaction = Transaction::new_unchecked(&self.conn, TransactionBehavior::Immediate)?;
        let changed = transaction.execute(
            "UPDATE tasks
             SET status = 'needs_input', lease_expires_at = NULL, parked_at = ?3, updated_at = ?3
             WHERE id = ?1 AND owner = ?2 AND status = 'claimed'",
            params![id, agent, now],
        )?;
        if changed != 1 {
            // Say why. This used to return `Ok(false)`, which the MCP surface
            // reported as `needs_input: false` — indistinguishable from a
            // successful no-op, and returned for every reason at once: wrong
            // owner, wrong status, no such task. An agent whose identity had
            // drifted was told nothing while its only route to explaining
            // itself silently did nothing, which is how a task ended up neither
            // provable nor parkable. A rejected park names the holder.
            let task = get_task_on(&transaction, id)?
                .ok_or_else(|| LodestarError::NotFound(id.to_string()))?;
            return Err(LodestarError::Invalid(format!(
                "task {id} was not parked: {agent} asked, but it is {} and held by {}. \
                 Only the agent holding a claimed task can park it with a question.",
                task.status.as_str(),
                task.owner.as_deref().unwrap_or("nobody"),
            )));
        }
        transaction.execute(
            "INSERT INTO task_qa (task_id, kind, body, author, audience, created_at)
             VALUES (?1, 'question', ?2, ?3, ?4, ?5)",
            params![id, question, agent, audience, now],
        )?;
        events::record(
            &transaction,
            id,
            TaskEventKind::Questioned,
            Some(agent),
            now,
            &match audience.as_deref() {
                Some(to) => format!(r#"{{"audience":"{to}"}}"#),
                None => String::new(),
            },
        )?;
        transaction.commit()?;
        Ok(true)
    }

    /// Unanswered questions addressed to one agent, oldest first (ADR-0046).
    ///
    /// This is a query over the durable thread, not a queue: nothing is
    /// delivered, reserved, or consumed, so two readers see the same rows and
    /// neither can lose one by reading it. A question stops appearing once the
    /// task carries a later answer, whoever wrote it — a human must always be
    /// able to unstick a pair of agents waiting on each other.
    pub fn pending_questions(&self, agent: &str) -> Result<Vec<TaskQa>> {
        let sql = format!(
            "SELECT {QA_COLS} FROM task_qa AS question
             WHERE question.kind = 'question' AND question.audience = ?1
               AND {UNANSWERED}
             ORDER BY question.id ASC"
        );
        let mut stmt = self.conn.prepare(&sql)?;
        let rows = stmt.query_map(params![agent], row_to_qa)?;
        collect(rows)
    }

    /// Every unanswered question addressed at a **human**, oldest first.
    ///
    /// A human has no agent id — `audience IS NULL` *is* the addressing
    /// (ADR-0046 clause 2) — so `pending_questions`, which matches an id, can
    /// never return one. Without this there is no way to list what is waiting
    /// on a person at all: you would have to walk every parked task and read
    /// its thread. Five tasks sat `awaiting_human` for up to seventy-five hours
    /// with no surface that could show them.
    ///
    /// Same posture as `pending_questions`: a query, never a queue. Nothing is
    /// delivered, reserved, or consumed, so two people reading cannot lose a
    /// question between them.
    ///
    /// The task must still be `needs_input`, matching `waits`: a question whose
    /// task has moved on is history, not a live wait, and listing it would
    /// invite an answer to something already resolved.
    ///
    /// The title travels with it because an inbox that forces a lookup per row
    /// to find out what it is about is not an inbox.
    pub fn questions_for_a_human(&self, now: i64) -> Result<Vec<HumanQuestion>> {
        let sql = format!(
            "SELECT question.id, question.task_id, tasks.title, question.author,
                    question.body, question.created_at
             FROM task_qa AS question
             JOIN tasks ON tasks.id = question.task_id
             WHERE question.kind = 'question' AND question.audience IS NULL
               AND tasks.status = 'needs_input'
               AND {UNANSWERED}
             ORDER BY question.id ASC"
        );
        let mut stmt = self.conn.prepare(&sql)?;
        let rows = stmt.query_map([], |row| {
            let asked_at: i64 = row.get(5)?;
            Ok(HumanQuestion {
                question_id: row.get(0)?,
                task_id: row.get(1)?,
                task_title: row.get(2)?,
                asked_by: row.get(3)?,
                question: row.get(4)?,
                asked_at,
                // Reported, never judged. How long is too long is a decision
                // nobody here is entitled to make on a reader's behalf.
                waiting_seconds: (now - asked_at).max(0),
            })
        })?;
        collect(rows)
    }

    /// Every agent currently parked waiting on an answer from another agent
    /// (ADR-0046), oldest question first.
    ///
    /// The task must still be `needs_input`: a question whose task has moved on
    /// is history, not a live wait, and reporting it would manufacture a stall
    /// that no longer exists.
    pub fn waits(&self) -> Result<Vec<Wait>> {
        let sql = format!(
            "SELECT question.task_id, question.author, question.audience, question.created_at
             FROM task_qa AS question
             JOIN tasks ON tasks.id = question.task_id
             WHERE question.kind = 'question' AND question.audience IS NOT NULL
               AND tasks.status = 'needs_input'
               AND {UNANSWERED}
             ORDER BY question.id ASC"
        );
        let mut stmt = self.conn.prepare(&sql)?;
        let rows = stmt.query_map([], |row| {
            Ok(Wait {
                task_id: row.get(0)?,
                waiter: row.get(1)?,
                waited_on: row.get(2)?,
                asked_at: row.get(3)?,
            })
        })?;
        collect(rows)
    }

    /// Answer a `needs_input` task's question (ADR-0020): records the durable
    /// answer and returns the task to `claimed` under the same owner with a fresh
    /// lease, preserving the `claim_started_at` evidence window.
    pub fn answer_question(
        &self,
        id: &str,
        answer: &str,
        author: &str,
        lease_secs: i64,
        now: i64,
    ) -> Result<bool> {
        let transaction = Transaction::new_unchecked(&self.conn, TransactionBehavior::Immediate)?;
        let changed = transaction.execute(
            "UPDATE tasks
             SET status = 'claimed', lease_expires_at = ?2, parked_at = NULL, updated_at = ?3
             WHERE id = ?1 AND status = 'needs_input'",
            params![id, now + lease_secs, now],
        )?;
        if changed != 1 {
            return Ok(false);
        }
        transaction.execute(
            "INSERT INTO task_qa (task_id, kind, body, author, audience, created_at)
             VALUES (?1, 'answer', ?2, ?3, NULL, ?4)",
            params![id, answer, author, now],
        )?;
        events::record(
            &transaction,
            id,
            TaskEventKind::Answered,
            Some(author),
            now,
            &format!(r#"{{"lease_secs":{lease_secs}}}"#),
        )?;
        transaction.commit()?;
        Ok(true)
    }

    /// Deliberately suspend a claimed task (ADR-0020): owner-guarded transition to
    /// `paused` that clears the live lease but keeps the owner and evidence window
    /// and records `parked_at`. A non-empty `reason` is appended to the durable
    /// thread as a note (ADR-0046). Resume with `resume_task`.
    pub fn pause_task(
        &self,
        id: &str,
        agent: &str,
        reason: Option<&str>,
        now: i64,
    ) -> Result<bool> {
        let transaction = Transaction::new_unchecked(&self.conn, TransactionBehavior::Immediate)?;
        let changed = transaction.execute(
            "UPDATE tasks
             SET status = 'paused', lease_expires_at = NULL, parked_at = ?3, updated_at = ?3
             WHERE id = ?1 AND owner = ?2 AND status = 'claimed'",
            params![id, agent, now],
        )?;
        if changed != 1 {
            return Ok(false);
        }
        append_note_on(&transaction, id, reason, agent, now)?;
        events::record(
            &transaction,
            id,
            TaskEventKind::Paused,
            Some(agent),
            now,
            &detail_json(reason),
        )?;
        transaction.commit()?;
        Ok(true)
    }

    /// Resume a paused task under the same owner (ADR-0020) with a fresh lease,
    /// preserving the `claim_started_at` evidence window.
    pub fn resume_task(&self, id: &str, agent: &str, lease_secs: i64, now: i64) -> Result<bool> {
        let transaction = Transaction::new_unchecked(&self.conn, TransactionBehavior::Immediate)?;
        let changed = transaction.execute(
            "UPDATE tasks
             SET status = 'claimed', lease_expires_at = ?3, parked_at = NULL, updated_at = ?4
             WHERE id = ?1 AND owner = ?2 AND status = 'paused'",
            params![id, agent, now + lease_secs, now],
        )?;
        if changed == 1 {
            events::record(
                &transaction,
                id,
                TaskEventKind::Resumed,
                Some(agent),
                now,
                &format!(r#"{{"lease_secs":{lease_secs}}}"#),
            )?;
        }
        transaction.commit()?;
        Ok(changed == 1)
    }

    /// The durable, append-only dialogue thread for a task, oldest first.
    pub fn task_qa(&self, task_id: &str) -> Result<Vec<TaskQa>> {
        let sql = format!("SELECT {QA_COLS} FROM task_qa WHERE task_id = ?1 ORDER BY id ASC");
        let mut stmt = self.conn.prepare(&sql)?;
        let rows = stmt.query_map(params![task_id], row_to_qa)?;
        collect(rows)
    }
}

/// Trim an addressee, treating blank as unaddressed (a human).
fn normalize_audience(audience: Option<&str>) -> Option<String> {
    audience
        .map(str::trim)
        .filter(|addressee| !addressee.is_empty())
        .map(str::to_string)
}

/// Append a state-change reason to a task's durable thread (ADR-0046). A blank
/// or absent reason writes nothing: an empty note is worse than none, because it
/// looks like an explanation was given.
pub(super) fn append_note_on(
    connection: &Connection,
    task_id: &str,
    reason: Option<&str>,
    author: &str,
    now: i64,
) -> Result<()> {
    let Some(reason) = reason.map(str::trim).filter(|body| !body.is_empty()) else {
        return Ok(());
    };
    connection.execute(
        "INSERT INTO task_qa (task_id, kind, body, author, audience, created_at)
         VALUES (?1, 'note', ?2, ?3, NULL, ?4)",
        params![task_id, reason, author, now],
    )?;
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::store::test_support::*;

    // ADR-0020: ask_question parks a claimed task in needs_input — owner-guarded,
    // lease cleared but owner + evidence window retained — records a durable
    // question, and a human answer returns it to claimed under the same owner
    // with a fresh lease.
    #[test]
    fn ask_question_parks_needs_input_and_answer_resumes_same_owner() {
        let s = store();
        let g = goal(&s);
        let t = s.create_task(&g.id, "task", "", None, NOW).unwrap();
        assert!(s.claim_task(&t.id, "alice", 60, NOW).unwrap());
        let window = s
            .get_task(&t.id)
            .unwrap()
            .unwrap()
            .claim_started_at
            .unwrap();

        // Non-owner cannot park it, and is told so rather than left guessing.
        let refused = s
            .ask_question(&t.id, "bob", "which db?", None, NOW + 1)
            .unwrap_err()
            .to_string();
        assert!(refused.contains("bob"), "{refused}");
        assert!(refused.contains("alice"), "{refused}");
        // Owner parks with a durable question.
        assert!(s
            .ask_question(&t.id, "alice", "which db?", None, NOW + 1)
            .unwrap());
        let parked = s.get_task(&t.id).unwrap().unwrap();
        assert_eq!(parked.status, TaskStatus::NeedsInput);
        assert_eq!(parked.owner.as_deref(), Some("alice"));
        assert_eq!(parked.claim_started_at, Some(window));
        assert_eq!(parked.lease_expires_at, None);
        assert_eq!(parked.parked_at, Some(NOW + 1));

        let thread = s.task_qa(&t.id).unwrap();
        assert_eq!(thread.len(), 1);
        assert_eq!(thread[0].kind, "question");
        assert_eq!(thread[0].body, "which db?");

        // A human answer returns it to claimed under the same owner, fresh lease,
        // preserved evidence window, and appends to the durable thread.
        assert!(s
            .answer_question(&t.id, "use sqlite", "human", 60, NOW + 2)
            .unwrap());
        let answered = s.get_task(&t.id).unwrap().unwrap();
        assert_eq!(answered.status, TaskStatus::Claimed);
        assert_eq!(answered.owner.as_deref(), Some("alice"));
        assert_eq!(answered.claim_started_at, Some(window));
        assert_eq!(answered.lease_expires_at, Some(NOW + 2 + 60));
        assert_eq!(answered.parked_at, None);
        let thread = s.task_qa(&t.id).unwrap();
        assert_eq!(thread.len(), 2);
        assert_eq!(thread[1].kind, "answer");
        assert_eq!(thread[1].body, "use sqlite");
    }

    /// Regression: `waiting_seconds` tracks the caller's `now`, and is the only
    /// field that does.
    ///
    /// THE BUG THIS PREVENTS. `HumanQuestion` derives `PartialEq`, and
    /// `waiting_seconds` is computed here as `now - asked_at` rather than
    /// stored. A test that reads the inbox twice and compares the whole value
    /// therefore compares a clock: two reads that straddle a one-second
    /// boundary are unequal even though nothing was consumed, reordered, or
    /// altered. That is exactly how
    /// `facade::executive::tests::reading_the_inbox_does_not_consume_it` failed
    /// in CI (run 33361472735) on a pull request that changed no Rust at all,
    /// and it would recur at random on any branch.
    ///
    /// Pinning it here is what makes excluding the field from that comparison
    /// correct rather than merely convenient: if `waiting_seconds` ever stops
    /// tracking `now`, or another field quietly becomes time-derived, this
    /// fails and the exclusion is revisited.
    #[test]
    fn only_waiting_seconds_moves_with_the_clock() {
        let s = store();
        let g = goal(&s);
        let t = s.create_task(&g.id, "task", "", None, NOW).unwrap();
        assert!(s.claim_task(&t.id, "alice", 60, NOW).unwrap());
        assert!(s
            .ask_question(&t.id, "alice", "which registry?", None, NOW)
            .unwrap());

        let at_ask = s.questions_for_a_human(NOW).unwrap();
        let a_minute_later = s.questions_for_a_human(NOW + 60).unwrap();
        assert_eq!(at_ask.len(), 1);
        assert_eq!(a_minute_later.len(), 1);

        assert_eq!(at_ask[0].waiting_seconds, 0);
        assert_eq!(a_minute_later[0].waiting_seconds, 60);

        // Everything else is stored, not derived, so it must be identical.
        let normalised = HumanQuestion {
            waiting_seconds: at_ask[0].waiting_seconds,
            ..a_minute_later[0].clone()
        };
        assert_eq!(
            at_ask[0], normalised,
            "waiting_seconds must be the only field that moves with the clock"
        );
    }

    /// A clock that has run backwards must not report a negative wait.
    #[test]
    fn a_wait_measured_before_it_was_asked_reports_zero_not_a_negative() {
        let s = store();
        let g = goal(&s);
        let t = s.create_task(&g.id, "task", "", None, NOW).unwrap();
        assert!(s.claim_task(&t.id, "alice", 60, NOW).unwrap());
        assert!(s
            .ask_question(&t.id, "alice", "which registry?", None, NOW)
            .unwrap());

        let backwards = s.questions_for_a_human(NOW - 5).unwrap();
        assert_eq!(backwards[0].waiting_seconds, 0);
    }

    // ADR-0046: a question may be addressed at a peer agent instead of a human,
    // and the peer discovers it by asking rather than by being pushed at. The
    // parking transition is deliberately identical to the human case: the owner
    // cannot proceed until answered either way, so the parking grace must still
    // protect the task from a peer that never replies.
    #[test]
    fn an_addressed_question_is_discoverable_by_its_peer_and_parks_identically() {
        let s = store();
        let g = goal(&s);
        let t = s.create_task(&g.id, "task", "", None, NOW).unwrap();
        assert!(s.claim_task(&t.id, "alice", 60, NOW).unwrap());

        // Nothing is waiting on anyone yet.
        assert!(s.pending_questions("bob").unwrap().is_empty());

        assert!(s
            .ask_question(
                &t.id,
                "alice",
                "did you already rename this?",
                Some("bob"),
                NOW + 1
            )
            .unwrap());

        // Same park as a question to a human: lease cleared, owner and evidence
        // window kept, reclaimable only after the parking grace.
        let parked = s.get_task(&t.id).unwrap().unwrap();
        assert_eq!(parked.status, TaskStatus::NeedsInput);
        assert_eq!(parked.owner.as_deref(), Some("alice"));
        assert_eq!(parked.lease_expires_at, None);
        assert_eq!(parked.parked_at, Some(NOW + 1));

        // Addressed to bob, so bob sees it and nobody else does.
        let waiting = s.pending_questions("bob").unwrap();
        assert_eq!(waiting.len(), 1);
        assert_eq!(waiting[0].task_id, t.id);
        assert_eq!(waiting[0].body, "did you already rename this?");
        assert_eq!(waiting[0].author, "alice");
        assert_eq!(waiting[0].audience.as_deref(), Some("bob"));
        assert!(s.pending_questions("carol").unwrap().is_empty());
        assert!(s.pending_questions("alice").unwrap().is_empty());

        // Reading is not consuming: a second reader sees the same row, so a
        // question can never be lost by being looked at.
        assert_eq!(s.pending_questions("bob").unwrap().len(), 1);

        // The peer answers; the question stops being pending and the asker resumes.
        assert!(s
            .answer_question(&t.id, "yes, yesterday", "bob", 60, NOW + 2)
            .unwrap());
        assert!(s.pending_questions("bob").unwrap().is_empty());
        assert_eq!(
            s.get_task(&t.id).unwrap().unwrap().status,
            TaskStatus::Claimed
        );
    }

    // ADR-0046: a human must always be able to unstick a pair of agents waiting
    // on each other, so an answer from anyone clears an addressed question. If
    // only the addressee could answer, two agents addressing each other would
    // deadlock until the parking grace elapsed a week later.
    #[test]
    fn a_human_can_answer_a_question_addressed_to_another_agent() {
        let s = store();
        let g = goal(&s);
        let t = s.create_task(&g.id, "task", "", None, NOW).unwrap();
        assert!(s.claim_task(&t.id, "alice", 60, NOW).unwrap());
        assert!(s
            .ask_question(&t.id, "alice", "which schema?", Some("bob"), NOW + 1)
            .unwrap());

        assert!(s
            .answer_question(&t.id, "bob is gone; use v2", "human", 60, NOW + 2)
            .unwrap());
        assert!(s.pending_questions("bob").unwrap().is_empty());
        let thread = s.task_qa(&t.id).unwrap();
        assert_eq!(thread[1].author, "human");
        assert_eq!(thread[1].audience, None);
    }

    // ADR-0046: addressing a question to yourself is refused. It would park the
    // task waiting on the only agent that cannot act while it is parked — a
    // self-deadlock that reads as a legitimate wait.
    #[test]
    fn a_question_addressed_to_its_own_asker_is_refused() {
        let s = store();
        let g = goal(&s);
        let t = s.create_task(&g.id, "task", "", None, NOW).unwrap();
        assert!(s.claim_task(&t.id, "alice", 60, NOW).unwrap());

        assert!(s
            .ask_question(&t.id, "alice", "well?", Some("alice"), NOW + 1)
            .is_err());
        // Refused means refused: the task is untouched, not parked.
        assert_eq!(
            s.get_task(&t.id).unwrap().unwrap().status,
            TaskStatus::Claimed
        );
    }

    // ADR-0046: blocking takes work away from whoever held it, so the reason is
    // recorded on the task's durable thread where its former owner can read it.
    // Previously block_task carried only a predecessor id, so an agent could
    // have its task blocked with no way to discover why — the same "message
    // points nowhere near the cause" failure the guard exists to prevent.
    #[test]
    fn blocking_and_pausing_record_their_reason_on_the_thread() {
        let s = store();
        let g = goal(&s);
        let t = s.create_task(&g.id, "task", "", None, NOW).unwrap();
        assert!(s.claim_task(&t.id, "alice", 60, NOW).unwrap());

        assert!(s
            .block_task(
                &t.id,
                None,
                Some("superseded by the ADR-0038 worktree model"),
                "human",
                NOW + 1
            )
            .unwrap());
        let thread = s.task_qa(&t.id).unwrap();
        assert_eq!(thread.len(), 1);
        assert_eq!(thread[0].kind, "note");
        assert_eq!(thread[0].body, "superseded by the ADR-0038 worktree model");
        assert_eq!(thread[0].author, "human");
        // A note is not addressed at anyone, so it never appears as pending work.
        assert_eq!(thread[0].audience, None);
        assert!(s.pending_questions("human").unwrap().is_empty());

        // A pause reason lands on the same thread, authored by the owner.
        assert!(s.reopen_task(&t.id, NOW + 2).unwrap());
        assert!(s.claim_task(&t.id, "alice", 60, NOW + 3).unwrap());
        assert!(s
            .pause_task(
                &t.id,
                "alice",
                Some("waiting on the release build"),
                NOW + 4
            )
            .unwrap());
        let thread = s.task_qa(&t.id).unwrap();
        assert_eq!(thread.len(), 2);
        assert_eq!(thread[1].kind, "note");
        assert_eq!(thread[1].body, "waiting on the release build");
        assert_eq!(thread[1].author, "alice");
    }

    // ADR-0046: a blank reason writes nothing. An empty note is worse than no
    // note, because a reader sees an entry and believes an explanation was given.
    #[test]
    fn a_blank_reason_writes_no_note() {
        let s = store();
        let g = goal(&s);
        let t = s.create_task(&g.id, "task", "", None, NOW).unwrap();
        assert!(s.claim_task(&t.id, "alice", 60, NOW).unwrap());

        assert!(s.pause_task(&t.id, "alice", Some("   "), NOW + 1).unwrap());
        assert!(s.task_qa(&t.id).unwrap().is_empty());

        // A losing (non-owner) pause must not write a note either: nothing
        // happened, so nothing is explained.
        assert!(s.resume_task(&t.id, "alice", 60, NOW + 2).unwrap());
        assert!(!s
            .pause_task(&t.id, "bob", Some("not mine to pause"), NOW + 3)
            .unwrap());
        assert!(s.task_qa(&t.id).unwrap().is_empty());
    }

    // ADR-0020: pause/resume are owner-guarded, clear the live lease but keep the
    // owner and the claim_started_at evidence window across the whole park.
    #[test]
    fn pause_and_resume_are_owner_guarded_and_preserve_the_window() {
        let s = store();
        let g = goal(&s);
        let t = s.create_task(&g.id, "task", "", None, NOW).unwrap();
        assert!(s.claim_task(&t.id, "alice", 60, NOW).unwrap());
        let window = s
            .get_task(&t.id)
            .unwrap()
            .unwrap()
            .claim_started_at
            .unwrap();

        assert!(!s.pause_task(&t.id, "bob", None, NOW + 1).unwrap());
        assert!(s.pause_task(&t.id, "alice", None, NOW + 1).unwrap());
        let paused = s.get_task(&t.id).unwrap().unwrap();
        assert_eq!(paused.status, TaskStatus::Paused);
        assert_eq!(paused.owner.as_deref(), Some("alice"));
        assert_eq!(paused.lease_expires_at, None);
        assert_eq!(paused.claim_started_at, Some(window));
        assert_eq!(paused.parked_at, Some(NOW + 1));

        assert!(!s.resume_task(&t.id, "bob", 60, NOW + 2).unwrap());
        assert!(s.resume_task(&t.id, "alice", 60, NOW + 2).unwrap());
        let resumed = s.get_task(&t.id).unwrap().unwrap();
        assert_eq!(resumed.status, TaskStatus::Claimed);
        assert_eq!(resumed.owner.as_deref(), Some("alice"));
        assert_eq!(resumed.claim_started_at, Some(window));
        assert_eq!(resumed.lease_expires_at, Some(NOW + 2 + 60));
        assert_eq!(resumed.parked_at, None);
    }

    // ADR-0020 anti-stranding: a parked task is owned (not reclaimable by the
    // pool) within the parking grace, but returns to the pool once it elapses so
    // a vanished owner cannot deadlock it forever.
    #[test]
    fn parked_task_is_reclaimable_only_after_the_parking_grace() {
        let s = store();
        let g = goal(&s);
        let t = s.create_task(&g.id, "task", "", None, NOW).unwrap();
        assert!(s.claim_task(&t.id, "alice", 60, NOW).unwrap());
        assert!(s.pause_task(&t.id, "alice", None, NOW).unwrap());

        // Within grace: owned, not reclaimable, not surfaced by next_task.
        let within = NOW + PARKING_GRACE_SECS - 1;
        assert!(!s.claim_task(&t.id, "bob", 60, within).unwrap());
        assert!(s.next_task(within).unwrap().is_none());

        // After grace: back in the pool for anyone, with a fresh window.
        let after = NOW + PARKING_GRACE_SECS + 1;
        assert_eq!(s.next_task(after).unwrap().unwrap().id, t.id);
        assert!(s.claim_task(&t.id, "bob", 60, after).unwrap());
        let reclaimed = s.get_task(&t.id).unwrap().unwrap();
        assert_eq!(reclaimed.status, TaskStatus::Claimed);
        assert_eq!(reclaimed.owner.as_deref(), Some("bob"));
        assert_eq!(reclaimed.parked_at, None);
        assert_eq!(reclaimed.claim_started_at, Some(after));
    }
}
